insert into summit_game_private.questions(id,game,difficulty,title,answers,explanation,source,public_data) values
('shuffle-easy-1','shuffle','easy','REVENUE','["REVENUE"]','REVENUE: Money earned from sales before subtracting costs.','','{"prompt":"Money earned from sales before subtracting costs.","wordLengths":[7]}'),
