('shuffle-medium-6','shuffle','medium','INVOICE','["INVOICE"]','INVOICE: A document asking a customer to pay for goods or services.','','{"prompt":"A document asking a customer to pay for goods or services.","wordLengths":[7]}'),
('shuffle-medium-7','shuffle','medium','FEEDBACK','["FEEDBACK"]','FEEDBACK: What users tell you about their experience.','','{"prompt":"What users tell you about their experience.","wordLengths":[8]}'),
('shuffle-medium-8','shuffle','medium','VALIDATION','["VALIDATION"]','VALIDATION: Testing whether evidence supports your business idea.','','{"prompt":"Testing whether evidence supports your business idea.","wordLengths":[10]}'),
('shuffle-medium-9','shuffle','medium','NETWORKING','["NETWORKING"]','NETWORKING: Building professional relationships and connections.','','{"prompt":"Building professional relationships and connections.","wordLengths":[10]}'),
('shuffle-medium-10','shuffle','medium','SCALABLE','["SCALABLE"]','SCALABLE: Able to grow without costs increasing at the same rate.','','{"prompt":"Able to grow without costs increasing at the same rate.","wordLengths":[8]}'),
('shuffle-hard-1','shuffle','hard','BREAK EVEN','["BREAK EVEN"]','BREAK EVEN: The point where total revenue equals total costs.','','{"prompt":"The point where total revenue equals total costs.","wordLengths":[5,4]}'),
